	return []HumanOperation{{Name: "PrepareAgentAssignment", Description: "Validate an agent recipe and prepare stable retry identities without starting a session. Execute the plan with the generated Workbench session and prompt operations; retain the recipe and receipt. This scaffold leaves Copilot context behavior unchanged."}, {Name: "Compile", Description: "Prepare a driving recipe: check the recipe and turn it into steps the controller can run."}, {Name: "GetDocument", Description: "Open one saved source document and read its words."}, {Name: "IngestDocument", Description: "Add a source document so people can find and cite it later."}, {Name: "PutEdge", Description: "Connect two ideas and record why they belong together."}, {Name: "GetGraph", Description: "Browse the ideas connected to a starting point."}, {Name: "PutNode", Description: "Add one idea to the shared knowledge map."}, {Name: "Search", Description: "Find saved knowledge that matches a question."}, {Name: "CancelSimulation", Description: "Request termination; inspect again to see whether provider cleanup is confirmed."}, {Name: "RecordSimulationEvents", Description: "Record bounded progress from an explicitly registered local simulator worker."}, {Name: "InspectSimulation", Description: "Inspect your simulator's progress, provider status, metrics and artifact location."}, {Name: "ListSimulations", Description: "List recent simulator examples and their actual execution states."}, {Name: "ReadSimulationLogs", Description: "Read bounded local job logs, including retained output after container cleanup."}, {Name: "SubmitSimulation", Description: "Queue a bounded simulator example using the operator's configured execution profile."}, {Name: "RebuildSimulationTrace", Description: "Rebuild a simulator trace from its retained OpenSearch source document."}, {Name: "GetSnapshot", Description: "Show the latest measured work and health report."}, {Name: "GetWorkbenchTheme", Description: "Read the active Workbench CSS and its host-owned file path. Edit workbench-theme.css at that path, then call ReloadWorkbenchTheme."}, {Name: "ReloadWorkbenchTheme", Description: "Reload the host-owned workbench-theme.css file after editing it. Missing or empty CSS restores the default; invalid UTF-8 or over 65536 bytes preserves the active theme. Browsers refresh within five seconds while visible. Use /ui/?theme=default to bypass broken CSS in one tab. No path or CSS input is accepted."}}
